package com.edunexa.app
import android.content.Intent
import android.os.Bundle
import android.widget.*
import androidx.appcompat.app.AppCompatActivity
class ToolsActivity:AppCompatActivity(){override fun onCreate(b:Bundle?){super.onCreate(b);val r=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;setPadding(36,36,36,36)};r.addView(TextView(this).apply{text="EduNexa Tools";textSize=28f;setTypeface(typeface,1)});r.addView(TextView(this).apply{text="Student • School • Cyber-Café Toolkit";setPadding(0,8,0,22)});fun section(t:String){r.addView(TextView(this).apply{text=t;textSize=19f;setTypeface(typeface,1);setPadding(0,22,0,8)})};fun add(t:String,cls:Class<*>){r.addView(Button(this).apply{text=t;isAllCaps=false;setOnClickListener{startActivity(Intent(this@ToolsActivity,cls))}})};section("Image Tools");add("Image Merge",ImageMergeActivity::class.java);add("Exam Form Photo & Signature Maker",PhotoSignatureToolActivity::class.java);add("Target KB Compressor",TargetKbToolActivity::class.java);section("PDF Tools");add("PDF Toolkit",PdfToolkitActivity::class.java);section("Student Tools");add("Marks & Percentage Calculator",ResultCalculatorActivity::class.java);r.addView(TextView(this).apply{text="More tools are being added as working modules, not placeholder buttons.";setPadding(0,24,0,16)});setContentView(ScrollView(this).apply{addView(r)})}}
